// LOVE DIVE: animated ocean and scuba diver.
const canvas = $('#ocean');
const c = canvas.getContext('2d');
const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;

let w = innerWidth;
let h = innerHeight;
let sceneTime = 0;
let last = 0;
let surfaceY = 0;
let diveStartedAt = 0;

function resize(){
    w = innerWidth;
    h = innerHeight;

    const dpr = Math.min(devicePixelRatio || 1, 2);
    canvas.width = Math.round(w * dpr);
    canvas.height = Math.round(h * dpr);
    c.setTransform(dpr, 0, 0, dpr, 0, 0);

    if (!surfaceY) surfaceY = h * .52;
}

window.addEventListener('resize', resize);
resize();

function polygon(points, fill){
    c.beginPath();

    points.forEach(([x, y], i) => {
        if (i === 0) c.moveTo(x, y);
        else c.lineTo(x, y);
    });

    c.closePath();
    c.fillStyle = fill;
    c.fill();
}

function drawBoat(x, y, t){
    c.save();
    c.translate(x, y + (reduced ? 0 : Math.sin(t * .001) * 2));

    polygon(
        [[-48,0],[48,0],[32,13],[-32,13]],
        '#173e50'
    );

    c.strokeStyle = '#e8f2ed';
    c.lineWidth = 2;
    c.beginPath();
    c.moveTo(-47, 2);
    c.quadraticCurveTo(0, 17, 47, 2);
    c.stroke();

    c.strokeStyle = '#f5f3e9';
    c.beginPath();
    c.moveTo(0, 0);
    c.lineTo(0, -67);
    c.stroke();

    polygon([[4,-62],[4,-8],[39,-8]], '#fff9ee');
    polygon([[-4,-52],[-4,-9],[-34,-9]], '#e9b9ad');

    c.restore();
}

function drawDiver(x, y, angle, scale, t){

    c.save();

    c.translate(
        x,
        y + Math.sin(t * 0.003) * 3
    );

    c.scale(scale, scale);

    //
    // FLOATIE
    //
    c.fillStyle = '#f4b7a3';

    c.beginPath();
    c.arc(0, 8, 18, 0, Math.PI * 2);
    c.fill();

    c.fillStyle = '#10354a';

    c.beginPath();
    c.arc(0, 8, 9, 0, Math.PI * 2);
    c.fill();


    //
    // LEGS
    //
    c.strokeStyle = '#c68b59';
    c.lineWidth = 4;
    c.lineCap = 'round';

    c.beginPath();
    c.moveTo(-4, 26);
    c.lineTo(-8, 42);
    c.stroke();

    c.beginPath();
    c.moveTo(4, 26);
    c.lineTo(8, 42);
    c.stroke();


    //
    // FINS
    //
    polygon(
        [
            [-13,42],
            [-4,42],
            [-8,57]
        ],
        '#63c6cb'
    );

    polygon(
        [
            [4,42],
            [13,42],
            [8,57]
        ],
        '#63c6cb'
    );


    //
    // BODY / WETSUIT
    //
    c.fillStyle = '#2f4c5e';

    c.fillRect(
        -8,
        -6,
        16,
        32
    );


    //
    // ARMS
    //
    c.strokeStyle = '#c68b59';
    c.lineWidth = 4;

    c.beginPath();
    c.moveTo(-8,3);
    c.lineTo(-18,10);
    c.stroke();

    c.beginPath();
    c.moveTo(8,3);
    c.lineTo(18,10);
    c.stroke();


    //
    // HEAD
    //
    c.fillStyle = '#c68b59';

    c.beginPath();
    c.arc(
        0,
        -18,
        12,
        0,
        Math.PI * 2
    );
    c.fill();


    //
    // SCUBA MASK
    //
    c.fillStyle = '#8fd5da';

    c.fillRect(
        -10,
        -24,
        20,
        12
    );

    c.strokeStyle = '#ffffff';
    c.lineWidth = 2;

    c.strokeRect(
        -10,
        -24,
        20,
        12
    );


    //
    // BREATHING TUBE
    //
    c.strokeStyle = '#12b494';
    c.lineWidth = 4;

    c.beginPath();

    c.moveTo(10, -18);
    c.lineTo(18, -18);
    c.lineTo(18, -40);

    c.stroke();


    //
    // BUBBLES
    //
    c.strokeStyle = 'rgba(221,250,247,.85)';
    c.lineWidth = 1.5;

    for(let i=0;i<4;i++){

        const bx =
            18 +
            Math.sin(
                t * 0.003 + i
            ) * 3;

        const by =
            -48 -
            i * 12 -
            (t * 0.01 % 10);

        c.beginPath();

        c.arc(
            bx,
            by,
            2 + i,
            0,
            Math.PI * 2
        );

        c.stroke();
    }

    c.restore();
}
``

function draw(t){
    const dt = Math.min(40, t - last || 16);
    last = t;

    if (!reduced) sceneTime += dt;

    const target = typeof targetDepth === 'number'
        ? targetDepth
        : 0;

    visualDepth += (
        target - visualDepth
    ) * (reduced ? 1 : .035);

    if (Math.abs(target - visualDepth) < .1){
        visualDepth = target;
    }

    const desired = screen === 'home'
        ? h * .52
        : screen === 'results'
            ? h * .36
            : h * .22 - Math.min(visualDepth, 20000) * .0035;

    surfaceY += (desired - surfaceY) * (reduced ? 1 : .045);

    const deep = Math.min(1, visualDepth / 6500);
    const sea = c.createLinearGradient(0, 0, 0, h);

    sea.addColorStop(
        0,
        `rgb(${Math.round(28-deep*18)},${Math.round(105-deep*70)},${Math.round(132-deep*79)})`
    );

    sea.addColorStop(
        1,
        `rgb(${Math.round(8-deep*5)},${Math.round(42-deep*28)},${Math.round(66-deep*38)})`
    );

    c.fillStyle = sea;
    c.fillRect(0, 0, w, h);

    // Sky
    if (surfaceY > 0){
        const sky = c.createLinearGradient(
            0, 0, 0, Math.max(1, surfaceY)
        );

        sky.addColorStop(0, '#9bcbd4');
        sky.addColorStop(1, '#edf3e9');

        c.fillStyle = sky;
        c.fillRect(0, 0, w, surfaceY + 2);

        c.fillStyle = '#f5dcaa';
        c.beginPath();
        c.arc(w * .78, Math.max(42, surfaceY * .34), 24, 0, Math.PI * 2);
        c.fill();

        c.strokeStyle = 'rgba(244,255,250,.55)';
        c.lineWidth = 2;
        c.beginPath();

        for (let x = 0; x <= w; x += 8){
            const y = surfaceY + (
                reduced ? 0 : Math.sin(x * .025 + sceneTime * .001) * 2
            );

            if (x === 0) c.moveTo(x, y);
            else c.lineTo(x, y);
        }

        c.stroke();
    }

    const boatX = w * .25;
    drawBoat(boatX, surfaceY, sceneTime);

    let dx = w * .2;
    let dy = surfaceY - 28;
    let angle = 0;

    if (screen === 'play'){
        const elapsed = reduced
            ? 2400
            : Math.max(0, t - diveStartedAt);

        const p = Math.min(1, elapsed / 2200);
        const ease = p * p * (3 - 2 * p);

        const underwaterY = Math.max(surfaceY + 150, h * .65)
            + Math.min(visualDepth * .25, h * .7);

        dx = boatX + 35 + (w * .90 - boatX - 35) * ease;
        dy = surfaceY - 30 + (
            underwaterY - (surfaceY - 30)
        ) * ease;

        angle = (1 - ease) * -.75
            + (reduced ? 0 : Math.sin(p * Math.PI) * .38);
    }

    if (screen === 'results') dy = surfaceY + 12;
    if (screen === 'home') dy = surfaceY - 28;

    dy = Math.max(35, Math.min(h - 45, dy));

    drawDiver(
        dx,
        dy,
        angle,
        1.2,
        sceneTime
    );

    const vignette = c.createLinearGradient(0, 0, 0, h);
    vignette.addColorStop(0, 'rgba(6,25,43,0)');
    vignette.addColorStop(1, 'rgba(4,20,37,.45)');

    c.fillStyle = vignette;
    c.fillRect(0, 0, w, h);

    requestAnimationFrame(draw);
}

requestAnimationFrame(draw);
home();
